-- The columns of Fivetran's Salesforce history-mode test seeds (fivetran/dbt_salesforce,
-- integration_tests/seeds, Apache-2.0), as Fivetran lands them in their own schema.
create schema salesforce_history;
create table salesforce_history.account (_fivetran_active varchar, _fivetran_start varchar, _fivetran_end varchar, _fivetran_synced varchar, account_number varchar, account_source varchar, annual_revenue varchar, billing_city varchar, billing_country varchar, billing_postal_code varchar, billing_state varchar, billing_street varchar, description varchar, id varchar, industry varchar, is_deleted varchar, last_activity_date varchar, last_referenced_date varchar, last_viewed_date varchar, master_record_id varchar, name varchar, number_of_employees varchar, owner_id varchar, ownership varchar, parent_id varchar, rating varchar, record_type_id varchar, shipping_city varchar, shipping_country varchar, shipping_postal_code varchar, shipping_state varchar, shipping_street varchar, type varchar, website varchar);
create table salesforce_history.opportunity (_fivetran_active varchar, _fivetran_start varchar, _fivetran_end varchar, _fivetran_synced varchar, account_id varchar, amount varchar, campaign_id varchar, close_date varchar, created_date varchar, description varchar, expected_revenue varchar, fiscal varchar, fiscal_quarter varchar, fiscal_year varchar, forecast_category varchar, forecast_category_name varchar, has_open_activity varchar, has_opportunity_line_item varchar, has_overdue_task varchar, id varchar, is_closed varchar, is_deleted varchar, is_won varchar, last_activity_date varchar, last_referenced_date varchar, last_viewed_date varchar, lead_source varchar, name varchar, next_step varchar, owner_id varchar, probability varchar, record_type_id varchar, stage_name varchar, synced_quote_id varchar, type varchar);
create table salesforce_history.contact (_fivetran_active varchar, _fivetran_start varchar, _fivetran_end varchar, id varchar, _fivetran_synced varchar, account_id varchar, email varchar, first_name varchar, is_deleted varchar, last_activity_date varchar, last_modified_by_id varchar, last_modified_date varchar, last_name varchar, last_referenced_date varchar, last_viewed_date varchar, mailing_city varchar, mailing_country varchar, mailing_country_code varchar, mailing_postal_code varchar, mailing_state varchar, mailing_street varchar, master_record_id varchar, mobile_phone varchar, name varchar, owner_id varchar, phone varchar, reports_to_id varchar, title varchar, lead_source varchar, description varchar, individual_id varchar, home_phone varchar);
